// Who you are up against, filled in when the template is added.
const WHO = {{who}};
// The bars are drawn out of this many chores, or out of the leader's count once it passes it.
const SCALE = 15;
const INK = '#121a2e';
const APRICOT = { light: '#ffd9b8', dark: '#3e2a1e' };
const WORDS = { light: INK, dark: '#ffebd8' };
const TRACK = { light: '#121a2e1F', dark: '#ffebd829' };
const BAR = { light: INK, dark: '#ffbe85' };
const KEY_WORDS = { light: '#ffd9b8', dark: '#2b1a10' };
const CROWN = 'M3 7l4.5 4L12 4l4.5 7L21 7l-2 12H5z';

// The key's fill sits twice: solid in the backdrop, which tinted and clear mode remove, and faint in the tree.
// So in full color it reads as one solid key, and in tinted mode its words still show on the faint one.
function key(u, ghost) {
  return { type: 'zstack', padding: { trailing: 15 * u, bottom: 15 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
    children: [
      { type: ghost ? 'zstack' : 'button', action: ghost ? null : 'did', children: [
        { type: 'zstack', padding: { vertical: 7 * u, horizontal: 11 * u },
          background: { type: 'rect', cornerRadius: 10 * u, fill: ghost ? BAR : { light: '#121a2e40', dark: '#ffbe8540' } },
          children: [
            { type: 'text', value: 'I did one', size: 12.5 * u, weight: 'bold', color: KEY_WORDS,
              opacity: ghost ? 0 : 1 },
          ] } ] },
    ] };
}

// Takes back a chore counted by mistake, beside the key.
function undo(last, u) {
  return { type: 'zstack', padding: { trailing: 102 * u, bottom: 15 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
    children: [
      { type: 'button', action: 'undo', rowId: last.id, label: 'Undo', children: [
        { type: 'symbol', name: 'arrow.uturn.backward', size: 12, weight: 'bold', color: WORDS,
          frame: { width: 30, height: 30 }, background: { light: '#121a2e14', dark: '#ffebd81F' }, clip: 'circle' } ] },
    ] };
}

function render(ctx) {
  // Sizes are in units of `u`, 1/170 of the widget's height.
  const u = ctx.height / 170;
  const d = ctx.data;
  const wide = ctx.family === 'medium';
  const top = Math.max(d.mine, d.theirs);
  const scale = Math.max(SCALE, top);
  // On a medium widget the rows take 76 percent of the width inside the padding.
  const rows = (ctx.width - 32 * u) * (wide ? 0.76 : 1);
  const nameWidth = (wide ? 66 : 64) * u;
  const row = (name, points) => ({ type: 'hstack', spacing: 8 * u, frame: { width: rows }, children: [
    { type: 'hstack', spacing: 4 * u, frame: { width: nameWidth, alignment: 'leading' }, children: [
      { type: 'text', value: name, size: 13.5 * u, weight: 'bold', color: WORDS, lineLimit: 1, minScale: 0.25 },
      points === top && top > 0 && { type: 'path', d: CROWN, viewBox: [0, 0, 24, 24], fill: '#e8a400',
        frame: { width: 14 * u, height: 14 * u } },
    ] },
    { type: 'zstack', align: 'leading', frame: { maxWidth: 'infinity', height: 10 * u }, children: [
      { type: 'rect', cornerRadius: 5 * u, fill: TRACK },
      points > 0 && { type: 'rect', cornerRadius: 5 * u, fill: BAR,
        frame: { width: (rows - nameWidth - (wide ? 24 : 20) * u - 16 * u) * points / scale } },
    ] },
    { type: 'text', value: points, size: 13.5 * u, weight: 'bold', color: WORDS, lineLimit: 1, minScale: 0.6,
      align: 'trailing', frame: { width: (wide ? 24 : 20) * u, alignment: 'trailing' } },
  ] });

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: APRICOT,
      children: [key(u, true)] },
    children: [
      { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: CROWN, viewBox: [0, 0, 24, 24], fill: WORDS, frame: { width: 15 * u, height: 15 * u } },
            { type: 'text', value: 'Chores this week', size: 13 * u, weight: 'bold', color: WORDS, lineLimit: 1,
              minScale: 0.8 } ] },
          { type: 'vstack', align: 'leading', spacing: 7 * u, padding: { top: 10.5 * u }, children: [
            row(WHO, d.theirs), row('You', d.mine)] },
        ] },
      wide && { type: 'text', value: "Winner picks Friday's movie", size: 12.5 * u, weight: 'bold', color: WORDS,
        opacity: 0.7, lineLimit: 1, minScale: 0.8, padding: { leading: 16 * u, bottom: 17 * u },
        frame: { maxWidth: ctx.width - 120 * u, maxHeight: 'infinity', alignment: 'bottomLeading' } },
      d.last && d.last.by.me && d.last.minutesAgo < 10 && undo(d.last, u),
      key(u, false),
    ],
  };
}
